<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient()
const requests=ref<any[]>([]),notes=ref<Record<string,string>>({}),logos=ref<Record<string,string>>({}),busy=ref(''),error=ref(''),message=ref('')
const inviteEmails=ref<Record<string,string>>({}),inviteBusy=ref(''),notice=ref('')
const pending=computed(()=>requests.value.filter(r=>r.status==='pending'))
async function load(){const r=await db.from('school_requests').select('id,school_name,school_domain,school_code,school_website,contact_name,contact_email,contact_position,contact_phone,notes,logo_path,status,created_at,review_notes,created_school_id').order('created_at',{ascending:false});requests.value=r.data||[];error.value=r.error?.message||'';logos.value={};for(const x of requests.value){if(!x.logo_path)continue;const s=await db.storage.from('school-logos').createSignedUrl(x.logo_path,1800);if(s.data?.signedUrl)logos.value[x.id]=s.data.signedUrl}}
onMounted(load)
async function review(r:any,approve:boolean){if(!confirm(`${approve?'Approve':'Reject'} ${r.school_name}? Approval creates the school but does NOT grant administrator access.`))return;busy.value=r.id;error.value='';message.value='';const res=await db.rpc('review_school_enquiry',{p_request_id:r.id,p_approve:approve,p_notes:notes.value[r.id]||null});busy.value='';if(res.error){error.value=res.error.message;return}message.value=approve?'School created. You can now invite its administrator.':'Request rejected.';await load();try{await adminPost('/api/admin/school-enquiries/notify',{requestId:r.id})}catch(e:any){notice.value='Review saved, but notification email failed: '+(e?.data?.statusMessage||e?.message||'Unknown error')}}
async function adminPost(url:string,body:any){const {data:{session}}=await db.auth.getSession();if(!session)throw new Error('Sign in again');return await $fetch(url,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`},body})}
async function invite(r:any){inviteBusy.value=r.id;error.value='';message.value='';try{const result=await adminPost('/api/admin/school-invitations/send',{requestId:r.id,email:inviteEmails.value[r.id]||r.contact_email}) as any;message.value=result.message}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Invitation failed'}finally{inviteBusy.value=''}}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>Pending School Requests ({{pending.length}})</h1><p>Visible only to SuperAdmins. Verify the school and representative before approval. No user is automatically made School Administrator.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success">{{message}}</p><div v-for="r in requests" :key="r.id" class="card" style="margin:16px 0"><h2>{{r.school_name}} — {{r.status}}</h2><img v-if="logos[r.id]" :src="logos[r.id]" :alt="`${r.school_name} logo`" style="max-width:160px;max-height:120px;object-fit:contain"><p><strong>School domain:</strong> {{r.school_domain}} · <strong>Website:</strong> {{r.school_website||'—'}}</p><p><strong>Contact:</strong> {{r.contact_name}} · {{r.contact_position}}</p><p><strong>Email:</strong> {{r.contact_email}} · <strong>Phone:</strong> {{r.contact_phone||'—'}}</p><p v-if="r.notes">{{r.notes}}</p><p v-if="r.review_notes">Review notes: {{r.review_notes}}</p><template v-if="r.status==='pending'"><label>Private review notes<textarea v-model="notes[r.id]" rows="2"></textarea></label><div class="actions"><button class="btn" :disabled="!!busy" @click="review(r,true)">Approve School</button><button class="btn" :disabled="!!busy" @click="review(r,false)">Reject</button></div></template><div v-if="r.status==='approved'" class="card"><h3>Invite first School Administrator</h3><p>Invitation must be accepted by a verified account with the same email. Access is not granted until acceptance.</p><label>Administrator email<input v-model="inviteEmails[r.id]" type="email" :placeholder="r.contact_email" /></label><button class="btn" :disabled="!!inviteBusy" @click="invite(r)">Send invitation</button></div></div><p v-if="!requests.length">No requests yet.</p></div></div></template>
